css:
.files {
  width: 240px;
  margin: 16px;
  padding: 0;
  list-style: none;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
  font-family: system-ui, sans-serif;
}

.file {
  padding: 8px 12px;
  border-bottom: 1px solid #e4e4e7;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
